import os
import queue
import threading
from dataclasses import dataclass
from typing import Generator, Optional

import pyaudio
import azure.cognitiveservices.speech as speechsdk


@dataclass
class InterimTranscript:
    text: str
    is_final: bool = False


class _TranscriptEventSink:
    def __init__(self, out_queue: "queue.Queue[Optional[InterimTranscript]]"):
        self._queue = out_queue

    def recognizing(self, evt) -> None:
        text = getattr(getattr(evt, "result", None), "text", "") or ""
        if text:
            self._queue.put(InterimTranscript(text=text, is_final=False))

    def recognized(self, evt) -> None:
        text = getattr(getattr(evt, "result", None), "text", "") or ""
        if text:
            self._queue.put(InterimTranscript(text=text, is_final=True))

    def canceled(self, evt) -> None:
        details = getattr(evt, "result", None)
        reason = getattr(details, "reason", None)
        error = getattr(details, "error_details", None)
        msg = f"Speech recognition canceled: reason={reason}, error={error}"
        self._queue.put(RuntimeError(msg))

    def session_stopped(self, evt) -> None:
        self._queue.put(None)


class StreamingMicrophoneTranscriber:
    def __init__(
        self,
        speech_key: Optional[str] = None,
        speech_region: Optional[str] = None,
        language: str = "en-US",
        sample_rate: int = 16000,
        chunk_size: int = 1024,
    ):
        self.speech_key = speech_key or os.getenv("AZURE_SPEECH_KEY")
        self.speech_region = speech_region or os.getenv("AZURE_SPEECH_REGION")
        if not self.speech_key or not self.speech_region:
            raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set")

        self.language = language
        self.sample_rate = sample_rate
        self.chunk_size = chunk_size

    def stream_transcripts(self) -> Generator[InterimTranscript, None, None]:
        speech_config = speechsdk.SpeechConfig(subscription=self.speech_key, region=self.speech_region)
        speech_config.speech_recognition_language = self.language

        stream_format = speechsdk.audio.AudioStreamFormat(samples_per_second=self.sample_rate, bits_per_sample=16, channels=1)
        push_stream = speechsdk.audio.PushAudioInputStream(stream_format)
        audio_config = speechsdk.audio.AudioConfig(stream=push_stream)
        recognizer = speechsdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

        q: "queue.Queue[Optional[InterimTranscript]]" = queue.Queue()
        sink = _TranscriptEventSink(q)

        recognizer.recognizing.connect(sink.recognizing)
        recognizer.recognized.connect(sink.recognized)
        recognizer.canceled.connect(sink.canceled)
        recognizer.session_stopped.connect(sink.session_stopped)

        def _mic_reader():
            pa = pyaudio.PyAudio()
            try:
                stream = pa.open(
                    format=pyaudio.paInt16,
                    channels=1,
                    rate=self.sample_rate,
                    input=True,
                    frames_per_buffer=self.chunk_size,
                )
                try:
                    while True:
                        data = stream.read(self.chunk_size, exception_on_overflow=False)
                        push_stream.write(data)
                except Exception:
                    pass
                finally:
                    try:
                        stream.stop_stream()
                    except Exception:
                        pass
                    try:
                        stream.close()
                    except Exception:
                        pass
            finally:
                try:
                    pa.terminate()
                except Exception:
                    pass

        reader_thread = threading.Thread(target=_mic_reader, daemon=True)
        reader_thread.start()

        recognizer.start_continuous_recognition()

        try:
            while True:
                item = q.get()
                if item is None:
                    break
                if isinstance(item, Exception):
                    raise item
                yield item
        finally:
            try:
                push_stream.close()
            except Exception:
                pass
            try:
                recognizer.stop_continuous_recognition()
            except Exception:
                pass


def stream_microphone_audio_transcripts() -> Generator[str, None, None]:
    transcriber = StreamingMicrophoneTranscriber()
    for item in transcriber.stream_transcripts():
        yield item.text
